package com.tripcraft.security;
import jakarta.servlet.FilterChain; import jakarta.servlet.ServletException; import jakarta.servlet.http.HttpServletRequest; import jakarta.servlet.http.HttpServletResponse; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; import java.util.List;
@Component public class JwtAuthFilter extends OncePerRequestFilter { private final JwtService jwt; public JwtAuthFilter(JwtService jwt){this.jwt=jwt;} protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{ String h=r.getHeader("Authorization"); if(h!=null&&h.startsWith("Bearer ")) try{String t=h.substring(7); SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(jwt.email(t),null,List.of(new SimpleGrantedAuthority(jwt.role(t)))));}catch(Exception ignored){} c.doFilter(r,s); } }
